      "page_number": 1,
      "panels": [
        {
          "panel_number": 2,
          "texts": [
            {
              "kind": "caption",
              "text": "The house was full; I asked for a room and agreed to share.",
              "caption_zone": "bottom_center"
            },
            {
              "kind": "speech",
              "speaker": "Peter Coffin",
              "text": "Hain’t no objections to sharing a harpooneer’s blanket?",
              "balloon_zone": "top_right",
              "speaker_region": "right",
              "source_evidence": "\"you haint no objections to sharing a harpooneer’s blanket, have ye?\""
            },
            {
              "kind": "speech",
              "speaker": "Ishmael",
              "text": "I never liked to sleep two in a bed.",
              "balloon_zone": "top_left",
              "speaker_region": "left",
              "source_evidence": "\"I told him that I never liked to sleep two in a bed;\""
            }
          ]
        }
      ]
    },
    {
      "page_number": 2,
      "panels": [
        {
          "panel_number": 3,
          "texts": [
            {
              "kind": "caption",
              "text": "I chose the bench; the planing and the bitter draughts defeated me.",
              "caption_zone": "top_right"
            },
            {
              "kind": "speech",
              "speaker": "Ishmael",
              "text": "I shan’t sleep with him. I’ll try the bench.",
              "balloon_zone": "bottom_left",
              "speaker_region": "left",
              "source_evidence": "\"I shan’t sleep with him. I’ll try the bench here.\""
            },
            {
              "kind": "speech",
              "speaker": "Peter Coffin",
              "text": "Wait—I’ll make ye snug enough.",
              "balloon_zone": "bottom_right",
              "speaker_region": "right",
              "source_evidence": "\"wait, I say, and I’ll make ye snug enough.\""
            }
          ]
        }
      ]
    },
    {
      "page_number": 4,
      "panels": [
        {
          "panel_number": 5,
          "texts": [
            {
              "kind": "caption",
              "text": "Since it was Sunday, I took the prodigious bed and eyed his outlandish gear.",
              "caption_zone": "top_center"
            },
            {
              "kind": "speech",
              "speaker": "Peter Coffin",
              "text": "Come along—I’ll give ye a glim in a jiffy.",
              "balloon_zone": "bottom_right",
              "speaker_region": "right",
              "source_evidence": "\"Come along here, I’ll give ye a glim in a jiffy;\""
            }
          ]
        }
      ]
    },
    {
      "page_number": 5,
      "panels": [
        {
          "panel_number": 7,
          "texts": [
            {
              "kind": "caption",
              "text": "He sprang into bed with the tomahawk-pipe.",
              "caption_zone": "top_right"
            },
            {
              "kind": "speech",
              "speaker": "Queequeg",
              "text": "Who-e debel you? You no speak-e—dam-me, I kill-e!",
              "balloon_zone": "top_center",
              "speaker_region": "center",
              "source_evidence": "\"Who-e debel you?—you no speak-e, dam-me, I kill-e.\""
            },
            {
              "kind": "speech",
              "speaker": "Ishmael",
              "text": "Landlord! For God’s sake—Peter Coffin! Watch! Angels! save me!",
              "balloon_zone": "bottom_left",
              "speaker_region": "left",
              "source_evidence": "\"Landlord, for God’s sake, Peter Coffin! ... Watch! ... Angels! save me!\""
            },
            {
              "kind": "speech",
              "speaker": "Peter Coffin",
              "text": "Don’t be afraid; Queequeg won’t harm a hair of your head.",
              "balloon_zone": "bottom_right",
              "speaker_region": "right",
              "source_evidence": "\"Don’t be afraid now ... Queequeg here wouldn’t harm a hair of your head.\""
            }
          ]
        },
        {
          "panel_number": 8,
          "texts": [
            {
              "kind": "caption",
              "text": "He stashed the tomahawk-pipe; I turned in again and slept soundly.",
              "caption_zone": "bottom_center"
            },
            {
              "kind": "thought",
              "speaker": "Ishmael",
              "text": "Better sleep with a sober cannibal than a drunken Christian.",
              "balloon_zone": "top_left",
              "speaker_region": "left",
              "source_evidence": "\"Better sleep with a sober cannibal than a drunken Christian.\""
            },
            {
              "kind": "speech",
              "speaker": "Ishmael",
              "text": "Tell him to stash that tomahawk-pipe. No smoking—I ain’t insured.",
              "balloon_zone": "bottom_left",
              "speaker_region": "left",
              "source_evidence": "\"tell him to stash his tomahawk there, or pipe... tell him to stop smoking... Besides, I ain’t insured.\""
            }
          ]
        }
      ]
    },
    {
      "page_number": 6,
      "panels": [
        {
          "panel_number": 2,
          "texts": [
            {
              "kind": "caption",
              "text": "I wriggled to rouse him and found the tomahawk-pipe by his side.",
              "caption_zone": "bottom_left"
            },
            {
              "kind": "speech",
              "speaker": "Ishmael",
              "text": "Queequeg! In the name of goodness—wake!",
              "balloon_zone": "top_left",
              "speaker_region": "left",
              "source_evidence": "\"Queequeg!—in the name of goodness, Queequeg, wake!\""
            }
          ]
        }
      ]
    }
  ]
